Definition c10_trace_1 : list drup_step :=
  decode_trace c10_records_1.

Definition c10_db_2 : clause_database :=
  Eval vm_compute in (add_drup_steps c10_db_1 c10_trace_1).

Lemma c10_chunk_1_checks :
  check_drup_chunk c10_db_1 c10_trace_1 = true.
Proof. vm_compute. reflexivity. Qed.

Lemma c10_final_empty :
  database_lookup c10_db_2 1934 = Some [].
Proof. vm_compute. reflexivity. Qed.

Theorem c10_base_unsatisfiable :
  forall rho, ~ satisfies_cnf rho (c10_base).
Proof.
intros rho Hbase.
pose proof (initial_database_sound rho (c10_base) Hbase) as Hdb0.
pose proof (check_drup_chunk_sound c10_db_0 c10_trace_0 c10_chunk_0_checks rho Hdb0) as Hdb1.
change (satisfies_database rho c10_db_1) in Hdb1.
pose proof (check_drup_chunk_sound c10_db_1 c10_trace_1 c10_chunk_1_checks rho Hdb1) as Hdb2.
change (satisfies_database rho c10_db_2) in Hdb2.
pose proof (Hdb2 1934 [] c10_final_empty) as Hfalse.
unfold eval_clause in Hfalse. discriminate.
Qed.
